// Golden SHA-256 vectors generated by `src/utils/sourceLockSidecar.ts` and
// asserted in `tests/source-lock-sidecar.mjs` to guarantee cross-language parity.
const GOLDEN_SELECTION_DIGEST: &str =
    "ab077f4318baf801584ca64f041aee5cc9116acd997ec5159faf9a09313d2209";
const GOLDEN_DOC0_STATE_DIGEST: &str =
    "fe4c197fe9f8a702515d0b0173953eb3f9fd7235359a30abf5127ac909a0034a";
const GOLDEN_DOC1_STATE_DIGEST: &str =
    "937767a1ba20e1ab5550245f7cdafbcfec8c7a03a4b0ac651c2a0ef883471fe9";
const GOLDEN_DOC2_STATE_DIGEST: &str =
    "dbd03cb539f27998678a8ebafeb7717b6adfe2cf5a896d5afcbbda5cc4a9e44f";
const GOLDEN_DOC1_SIDECAR_DIGEST: &str =
    "2e03967a4794e263523e9cac25454c03556d9a060f27c96a924292cb6adbf482";
const GOLDEN_DOC2_SIDECAR_DIGEST: &str =
    "19cc8d93199635cf5eec72542d3f3b11611c19fba98e2bb0f50ff9132f8c7e5c";
const GOLDEN_DOC3_SIDECAR_DIGEST: &str =
    "6a4a40aa3957bc0de1bff713977b23c7f4d2e9018e47380c5e1063e1a5a8f7e4";

fn sample_frame() -> CoordinateFrame {
    CoordinateFrame {
        id: "world-v1".into(),
        canvas: [31090.0, 11008.0],
        origin: [2607.0, 875.0],
        units: SOURCE_LOCK_COORDINATE_UNITS.into(),
    }
}

fn sample_bindings() -> Vec<SourceBinding> {
    vec![
        SourceBinding {
            source_id: 42,
            path: "/artwork/DSC_3687.NEF".into(),
            sha256: "11".repeat(32),
            station_id: 7,
            capture_group_id: 3,
            source_to_world_sha256: "aa".repeat(32),
        },
        SourceBinding {
            source_id: 43,
            path: "/artwork/DSC_3688.NEF".into(),
            sha256: "22".repeat(32),
            station_id: 7,
            capture_group_id: 3,
            source_to_world_sha256: "bb".repeat(32),
        },
    ]
}

fn sample_region() -> WorldRegion {
    WorldRegion {
        polygon_world: vec![[120.0, 80.0], [640.0, 80.0], [640.0, 500.0], [120.0, 500.0]],
        bbox: [120.0, 80.0, 520.0, 420.0],
    }
}

fn sample_lock() -> SourceLock {
    SourceLock {
        lock_id: "lock-0001".into(),
        status: SourceLockStatus::Active,
        region: sample_region(),
        requested_sources: vec![42],
        policy: SourceLockPolicy::SingleSource,
        eligible_tiles: 17,
        selection_digest: GOLDEN_SELECTION_DIGEST.into(),
        created_event: 1,
        stale_reason: None,
    }
}

fn sample_manual_review() -> ManualReviewRegion {
    ManualReviewRegion {
        region_id: "review-0002".into(),
        polygon_world: sample_region().polygon_world,
        reason: "paper_seam_review".into(),
        excluded_from_quality_gate: true,
        created_event: 2,
    }
}

fn sample_doc1() -> SourceLockDocument {
    let lock = sample_lock();
    let lock_value = serde_json::to_value(&lock).expect("lock should serialize");
    SourceLockDocument {
        schema: SOURCE_LOCK_SCHEMA_VERSION,
        run_id: "native-fixture-001".into(),
        input_manifest_sha256: "mm".repeat(32),
        coordinate_frame: sample_frame(),
        source_bindings: sample_bindings(),
        locks: vec![lock],
        manual_review_regions: Vec::new(),
        history: SourceLockHistory {
            head: 1,
            events: vec![SourceLockEvent {
                event_id: 1,
                kind: SourceLockEventKind::AddSourceLock,
                inverse_kind: SourceLockEventKind::RemoveSourceLock,
                before_digest: GOLDEN_DOC0_STATE_DIGEST.into(),
                after_digest: GOLDEN_DOC1_STATE_DIGEST.into(),
                coordinate_frame_id: "world-v1".into(),
                target_id: "lock-0001".into(),
                reverted_event_id: None,
                payload: EventPayloadField::Present(lock_value),
            }],
        },
    }
}

fn sample_doc2() -> SourceLockDocument {
    let mut doc = sample_doc1();
    let review = sample_manual_review();
    let review_value = serde_json::to_value(&review).expect("review should serialize");
    doc.manual_review_regions.push(review);
    doc.history.head = 2;
    doc.history.events.push(SourceLockEvent {
        event_id: 2,
        kind: SourceLockEventKind::AddManualReviewRegion,
        inverse_kind: SourceLockEventKind::RemoveManualReviewRegion,
        before_digest: GOLDEN_DOC1_STATE_DIGEST.into(),
        after_digest: GOLDEN_DOC2_STATE_DIGEST.into(),
        coordinate_frame_id: "world-v1".into(),
        target_id: "review-0002".into(),
        reverted_event_id: None,
        payload: EventPayloadField::Present(review_value),
    });
    doc
}

fn sample_doc3() -> SourceLockDocument {
    let mut doc = sample_doc2();
    let review_value =
        serde_json::to_value(sample_manual_review()).expect("review should serialize");
    doc.manual_review_regions.clear();
    doc.history.head = 3;
    doc.history.events.push(SourceLockEvent {
        event_id: 3,
        kind: SourceLockEventKind::Undo,
        inverse_kind: SourceLockEventKind::AddManualReviewRegion,
        before_digest: GOLDEN_DOC2_STATE_DIGEST.into(),
        after_digest: GOLDEN_DOC1_STATE_DIGEST.into(),
        coordinate_frame_id: "world-v1".into(),
        target_id: "review-0002".into(),
        reverted_event_id: Some(2),
        payload: EventPayloadField::Present(review_value),
    });
    doc
}

#[test]
fn canonical_digests_match_typescript_golden_vectors_bit_for_bit() {
    let selection = compute_selection_digest(
        &[42],
        &sample_region(),
        &"cc".repeat(32),
        &sample_bindings(),
        SourceLockPolicy::SingleSource,
        "world-v1",
    )
    .expect("selection digest should compute");
    assert_eq!(selection, GOLDEN_SELECTION_DIGEST);

    // Source ordering independence for allowed_sources.
    let order_ab = compute_selection_digest(
        &[42, 43],
        &sample_region(),
        &"cc".repeat(32),
        &sample_bindings(),
        SourceLockPolicy::AllowedSources,
        "world-v1",
    )
    .expect("ordered digest");
    let order_ba = compute_selection_digest(
        &[43, 42, 42],
        &sample_region(),
        &"cc".repeat(32),
        &sample_bindings(),
        SourceLockPolicy::AllowedSources,
        "world-v1",
    )
    .expect("reversed duplicate digest");
    assert_eq!(order_ab, order_ba);

    assert_eq!(
        compute_state_digest(&[], &[]).expect("empty state digest"),
        GOLDEN_DOC0_STATE_DIGEST
    );
    let doc1 = sample_doc1();
    assert_eq!(
        compute_state_digest(&doc1.locks, &doc1.manual_review_regions).expect("doc1 state"),
        GOLDEN_DOC1_STATE_DIGEST
    );
    assert_eq!(
        compute_sidecar_digest(&doc1).expect("doc1 sidecar digest"),
        GOLDEN_DOC1_SIDECAR_DIGEST
    );

    let doc2 = sample_doc2();
    assert_eq!(
        compute_state_digest(&doc2.locks, &doc2.manual_review_regions).expect("doc2 state"),
        GOLDEN_DOC2_STATE_DIGEST
    );
    assert_eq!(
        compute_sidecar_digest(&doc2).expect("doc2 sidecar digest"),
        GOLDEN_DOC2_SIDECAR_DIGEST
    );

    let doc3 = sample_doc3();
    assert_eq!(
        compute_sidecar_digest(&doc3).expect("doc3 sidecar digest"),
        GOLDEN_DOC3_SIDECAR_DIGEST
    );
    assert!(
        validate_source_lock_integrity(&doc3).is_empty(),
        "valid doc3 should have zero integrity errors"
    );

    // Parse verbatim integer-formatted JSON serialized by TypeScript and verify
    // it yields the exact same sidecar SHA-256 digest.
    let ts_raw_doc1 = r#"{
  "schema": 1,
  "run_id": "native-fixture-001",
  "input_manifest_sha256": "mmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmm",
  "coordinate_frame": {"id": "world-v1", "canvas": [31090, 11008], "origin": [2607, 875], "units": "native_output_pixels"},
  "source_bindings": [
    {"source_id": 42, "path": "/artwork/DSC_3687.NEF", "sha256": "1111111111111111111111111111111111111111111111111111111111111111", "station_id": 7, "capture_group_id": 3, "source_to_world_sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"},
    {"source_id": 43, "path": "/artwork/DSC_3688.NEF", "sha256": "2222222222222222222222222222222222222222222222222222222222222222", "station_id": 7, "capture_group_id": 3, "source_to_world_sha256": "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"}
  ],
  "locks": [{
    "lock_id": "lock-0001",
    "status": "active",
    "region": {"polygon_world": [[120, 80], [640, 80], [640, 500], [120, 500]], "bbox": [120, 80, 520, 420]},
    "requested_sources": [42],
    "policy": "single_source",
    "eligible_tiles": 17,
    "selection_digest": "ab077f4318baf801584ca64f041aee5cc9116acd997ec5159faf9a09313d2209",
    "created_event": 1,
    "stale_reason": null
  }],
  "manual_review_regions": [],
  "history": {
    "head": 1,
    "events": [{
      "event_id": 1,
      "kind": "add_source_lock",
      "inverse_kind": "remove_source_lock",
      "before_digest": "fe4c197fe9f8a702515d0b0173953eb3f9fd7235359a30abf5127ac909a0034a",
      "after_digest": "937767a1ba20e1ab5550245f7cdafbcfec8c7a03a4b0ac651c2a0ef883471fe9",
      "coordinate_frame_id": "world-v1",
      "target_id": "lock-0001",
      "payload": {
        "lock_id": "lock-0001",
        "status": "active",
        "region": {"polygon_world": [[120, 80], [640, 80], [640, 500], [120, 500]], "bbox": [120, 80, 520, 420]},
        "requested_sources": [42],
        "policy": "single_source",
        "eligible_tiles": 17,
        "selection_digest": "ab077f4318baf801584ca64f041aee5cc9116acd997ec5159faf9a09313d2209",
        "created_event": 1,
        "stale_reason": null
      }
    }]
  }
}"#;
    let parsed_ts_doc1 =
        parse_source_lock_document_str(ts_raw_doc1).expect("TS raw JSON doc1 should parse");
    assert_eq!(
        compute_sidecar_digest(&parsed_ts_doc1).expect("TS raw doc1 digest"),
        GOLDEN_DOC1_SIDECAR_DIGEST
    );
}

#[test]
fn parser_rejects_malformed_schema_non_monotonic_history_and_bad_regions() {
    assert!(parse_source_lock_document_str("{invalid").is_err());

    let mut bad_schema = sample_doc1();
    bad_schema.schema = 2;
    let raw = serde_json::to_string(&bad_schema).unwrap();
    assert!(parse_source_lock_document_str(&raw).is_err());

    let mut bad_units = sample_doc1();
    bad_units.coordinate_frame.units = "screen_css_pixels".into();
    let raw = serde_json::to_string(&bad_units).unwrap();
    assert!(parse_source_lock_document_str(&raw).is_err());

    let mut non_monotonic = sample_doc2();
    non_monotonic.history.events[1].event_id = 1;
    let raw = serde_json::to_string(&non_monotonic).unwrap();
    assert!(parse_source_lock_document_str(&raw).is_err());

    let mut bad_review = sample_doc2();
    bad_review.manual_review_regions[0].excluded_from_quality_gate = false;
    let raw = serde_json::to_string(&bad_review).unwrap();
    assert!(parse_source_lock_document_str(&raw).is_err());

    let mut duplicate_source = sample_doc1();
    duplicate_source
        .source_bindings
        .push(sample_bindings()[0].clone());
    let raw = serde_json::to_string(&duplicate_source).unwrap();
    assert!(parse_source_lock_document_str(&raw).is_err());
}

#[test]
fn integrity_detects_unregistered_source_ids_and_broken_event_digest_chains() {
    let mut bad_source = sample_doc1();
    bad_source.locks[0].requested_sources = vec![999];
    let errors = validate_source_lock_integrity(&bad_source);
    assert!(errors.iter().any(|err| err == "unregistered_source_id:999"));

    let mut broken_chain = sample_doc2();
    broken_chain.history.events[1].before_digest = "00".repeat(32);
    let errors = validate_source_lock_integrity(&broken_chain);
    assert!(
        errors
            .iter()
            .any(|err| err == "event_digest_chain_broken:1->2")
    );
}

#[test]
fn staleness_reconciliation_flags_run_frame_manifest_and_source_changes() {
    let doc1 = sample_doc1();
    let matching_run = CurrentRunBinding {
        run_id: doc1.run_id.clone(),
        input_manifest_sha256: doc1.input_manifest_sha256.clone(),
        coordinate_frame: sample_frame(),
        source_bindings: sample_bindings(),
    };
    let clean = reconcile_document_staleness(&doc1, &matching_run);
    assert_eq!(clean.newly_stale_count, 0);
    assert!(clean.mismatch_reasons.is_empty());
    assert_eq!(clean.doc.locks[0].status, SourceLockStatus::Active);

    let mut origin_shifted = matching_run.clone();
    origin_shifted.coordinate_frame.origin = [2608.0, 875.0];
    let shifted = reconcile_document_staleness(&doc1, &origin_shifted);
    assert_eq!(shifted.newly_stale_count, 1);
    assert_eq!(shifted.doc.locks[0].status, SourceLockStatus::Stale);
    assert_eq!(
        shifted.doc.locks[0].stale_reason.as_deref(),
        Some("coordinate_frame_or_crop_changed")
    );

    let mut digest_changed = matching_run.clone();
    digest_changed.source_bindings[0].sha256 = "99".repeat(32);
    let source_stale = reconcile_document_staleness(&doc1, &digest_changed);
    assert_eq!(
        source_stale.doc.locks[0].stale_reason.as_deref(),
        Some("source_digest_changed:42")
    );

    let mut transform_changed = matching_run.clone();
    transform_changed.source_bindings[0].source_to_world_sha256 = "ff".repeat(32);
    let pose_stale = reconcile_document_staleness(&doc1, &transform_changed);
    assert_eq!(
        pose_stale.doc.locks[0].stale_reason.as_deref(),
        Some("source_transform_changed:42")
    );

    let mut different_run = matching_run;
    different_run.run_id = "native-fixture-002".into();
    let run_stale = reconcile_document_staleness(&doc1, &different_run);
    assert_eq!(run_stale.newly_stale_count, 1);
    assert_eq!(
        run_stale.doc.locks[0].stale_reason.as_deref(),
        Some("run_id_changed")
    );
}

#[test]
fn world_point_constraints_follow_precedence_and_fail_closed_on_conflicts() {
    let mut doc = sample_doc2();
    // Outside region -> Auto.
    assert_eq!(
        resolve_world_point_constraint(&doc, 10.0, 10.0),
        WorldPointConstraint::Auto
    );
    // Inside active single_source lock -> SingleSource(42).
    assert_eq!(
        resolve_world_point_constraint(&doc, 300.0, 250.0),
        WorldPointConstraint::SingleSource {
            source_id: 42,
            lock_ids: vec!["lock-0001".into()],
        }
    );
    assert_eq!(
        find_manual_review_region_at_point(&doc, 300.0, 250.0).map(|r| r.region_id.as_str()),
        Some("review-0002")
    );

    // Overlapping allowed_sources [42, 43] narrows cleanly to SingleSource(42).
    let mut allowed_lock = sample_lock();
    allowed_lock.lock_id = "lock-0002".into();
    allowed_lock.policy = SourceLockPolicy::AllowedSources;
    allowed_lock.requested_sources = vec![42, 43];
    doc.locks.push(allowed_lock);
    assert_eq!(
        resolve_world_point_constraint(&doc, 300.0, 250.0),
        WorldPointConstraint::SingleSource {
            source_id: 42,
            lock_ids: vec!["lock-0001".into(), "lock-0002".into()],
        }
    );

    // Contradictory active lock requiring only source 43 -> empty intersection -> Conflict.
    let mut conflicting_lock = sample_lock();
    conflicting_lock.lock_id = "lock-0003".into();
    conflicting_lock.requested_sources = vec![43];
    doc.locks.push(conflicting_lock);
    assert_eq!(
        resolve_world_point_constraint(&doc, 300.0, 250.0),
        WorldPointConstraint::Conflict {
            lock_ids: vec!["lock-0001".into(), "lock-0002".into(), "lock-0003".into()],
        }
    );

    // Any stale lock covering the point takes top precedence.
    doc.locks[2].status = SourceLockStatus::Stale;
    assert_eq!(
        resolve_world_point_constraint(&doc, 300.0, 250.0),
        WorldPointConstraint::BlockedByStaleOrUnresolved {
            lock_ids: vec!["lock-0003".into()],
        }
    );
}

#[test]
fn manual_review_qg_accounting_preserves_failures_and_fails_closed() {
    let doc2 = sample_doc2();
    let observations = vec![
        QualityGateTileObservation {
            tile_id: "t1".into(),
            failed: true,
            manual_region_id: Some("review-0002".into()),
        },
        QualityGateTileObservation {
            tile_id: "t2".into(),
            failed: false,
            manual_region_id: None,
        },
    ];
    let insufficient = compute_manual_review_quality_gate_accounting(&observations, &doc2, 4);
    assert_eq!(insufficient.all_tiles, 2);
    assert_eq!(insufficient.auto_eligible_tiles, 1);
    assert_eq!(insufficient.failed_all_tiles, 1);
    assert_eq!(insufficient.failed_auto_eligible_tiles, 0);
    assert_eq!(insufficient.excluded_tiles.len(), 1);
    assert_eq!(
        insufficient.verdict,
        ManualReviewQualityGateVerdict::InsufficientEvidence
    );

    let pass = compute_manual_review_quality_gate_accounting(&observations, &doc2, 1);
    assert_eq!(pass.verdict, ManualReviewQualityGateVerdict::Pass);
    assert_eq!(pass.failed_all_tiles, 1);
}

#[test]
fn on_disk_export_bundle_audit_detects_valid_stale_mismatch_and_tampered_events() {
    let dir = tempdir().expect("tempdir");
    let tiff_path = dir.path().join("artwork.tif");
    let sidecar_path = dir.path().join("source-locks.json");
    let events_path = dir.path().join("source-locks.events.jsonl");

    fs::write(&tiff_path, b"MM\x00*\x00\x00\x00\x08synthetic-native-tiff").expect("write tiff");
    let expected_tiff_sha = sha256_file_hex(&tiff_path).expect("hash tiff");

    let doc3 = sample_doc3();
    let sidecar_json = serde_json::to_string_pretty(&doc3).expect("serialize doc3");
    let events_jsonl = doc3
        .history
        .events
        .iter()
        .map(|ev| serde_json::to_string(ev).unwrap())
        .collect::<Vec<_>>()
        .join("\n")
        + "\n";
    fs::write(&sidecar_path, &sidecar_json).expect("write sidecar");
    fs::write(&events_path, &events_jsonl).expect("write events jsonl");

    // 1. Clean valid export bundle.
    let valid = audit_export_bundle_on_disk(
        &tiff_path,
        &sidecar_path,
        Some(&events_path),
        &expected_tiff_sha,
        GOLDEN_DOC3_SIDECAR_DIGEST,
        None,
    )
    .expect("valid audit");
    assert_eq!(valid.status, ExportBindingStatus::Valid);
    assert!(valid.can_publish_as_confirmed);
    assert_eq!(valid.sidecar_sha256, GOLDEN_DOC3_SIDECAR_DIGEST);
    assert_eq!(valid.summary.active_locks, 1);
    assert_eq!(valid.summary.active_lock_area_px, 520 * 420);
    assert_eq!(valid.summary.locked_eligible_tiles, 17);
    assert_eq!(valid.summary.event_count, 3);

    // 2. Sidecar edited after export -> stale_export.
    let stale_export = audit_export_bundle_on_disk(
        &tiff_path,
        &sidecar_path,
        Some(&events_path),
        &expected_tiff_sha,
        GOLDEN_DOC1_SIDECAR_DIGEST,
        None,
    )
    .expect("stale_export audit");
    assert_eq!(stale_export.status, ExportBindingStatus::StaleExport);
    assert!(!stale_export.can_publish_as_confirmed);

    // 3. TIFF modified after export -> binding_mismatch.
    fs::write(&tiff_path, b"MM\x00*\x00\x00\x00\x08mutated-native-tiff").expect("mutate tiff");
    let mismatch = audit_export_bundle_on_disk(
        &tiff_path,
        &sidecar_path,
        Some(&events_path),
        &expected_tiff_sha,
        GOLDEN_DOC3_SIDECAR_DIGEST,
        None,
    )
    .expect("binding_mismatch audit");
    assert_eq!(mismatch.status, ExportBindingStatus::BindingMismatch);
    assert!(!mismatch.can_publish_as_confirmed);

    // Restore original TIFF, tamper events.jsonl -> events_log_mismatch.
    fs::write(&tiff_path, b"MM\x00*\x00\x00\x00\x08synthetic-native-tiff").expect("restore tiff");
    let truncated_events = events_jsonl.lines().take(2).collect::<Vec<_>>().join("\n") + "\n";
    fs::write(&events_path, truncated_events).expect("truncate events");
    let events_mismatch = audit_export_bundle_on_disk(
        &tiff_path,
        &sidecar_path,
        Some(&events_path),
        &expected_tiff_sha,
        GOLDEN_DOC3_SIDECAR_DIGEST,
        None,
    )
    .expect("events mismatch audit");
    assert_eq!(
        events_mismatch.status,
        ExportBindingStatus::EventsLogMismatch
    );
    assert!(!events_mismatch.can_publish_as_confirmed);

    // Restore events.jsonl, reconcile against shifted run frame -> has_stale_or_unresolved_locks.
    fs::write(&events_path, &events_jsonl).expect("restore events");
    let shifted_run = CurrentRunBinding {
        run_id: doc3.run_id.clone(),
        input_manifest_sha256: doc3.input_manifest_sha256.clone(),
        coordinate_frame: CoordinateFrame {
            origin: [9999.0, 875.0],
            ..sample_frame()
        },
        source_bindings: sample_bindings(),
    };
    let stale_run = audit_export_bundle_on_disk(
        &tiff_path,
        &sidecar_path,
        Some(&events_path),
        &expected_tiff_sha,
        GOLDEN_DOC3_SIDECAR_DIGEST,
        Some(&shifted_run),
    )
    .expect("stale run audit");
    assert_eq!(
        stale_run.status,
        ExportBindingStatus::HasStaleOrUnresolvedLocks
    );
    assert!(!stale_run.can_publish_as_confirmed);
}
